import {htmlCopy} from './locale.js';
import {icon} from './ui-icons.js';

export const beginnerTerms={
  Species:{why:"Check your Species traits before choosing related options. Species does not decide your Class or personality.",definition:'Species describes your character’s ancestry. It gives you traits such as senses, movement, or special abilities.',
    examples:['A Dwarf can see in darkness within the range of their Darkvision.','A Dragonborn can use a Breath Weapon whose damage type comes from their ancestry.'],pages:'20, 84–86'},
  Background:{why:"Review your granted feat and training, then choose ability increases and starting equipment in their own steps.",definition:'Background describes what you did before adventuring. It gives you an Origin feat, skill and tool proficiencies, and starting gear or money. It also sets which ability scores you can increase.',
    examples:['A Sage gains proficiency in Arcana and History.','A Soldier gains Savage Attacker, an Origin feat that can improve a weapon damage roll.'],pages:'19–20, 83'},
  Proficiency:{why:"Look for the specific skill, save, weapon, or tool you are trained in before adding this bonus.",definition:'Proficiency means you add your Proficiency Bonus when you make a roll covered by that training. At level 1, that bonus is +2.',
    examples:['If you have Athletics proficiency, add +2 to a level 1 Athletics check to climb a difficult wall, in addition to your Strength modifier.','If you have proficiency with a Longsword, add +2 to a level 1 attack roll with it. The bonus is for the attack roll.'],pages:'9–11'},
  "Class": {"definition": "Class describes your adventuring training. It determines features, Hit Dice, saving throw proficiencies, and how you gain abilities as you level up.", "examples": ["A level 1 Fighter can use Second Wind to regain Hit Points.", "A level 1 Wizard records spells in a spellbook and prepares spells from it."], "why": "Choose the kind of actions you want to take; your Class determines which options become available.", "pages": "19, 28–82"},
  "Skill": {"definition": "A skill is a category of tasks that can use an ability check. Skill proficiency adds your Proficiency Bonus when that skill applies.", "examples": ["Athletics often uses Strength to swim through rough water.", "Perception often uses Wisdom to notice something easy to miss."], "why": "Pick skills for tasks you want training in; proficiency does not guarantee success.", "pages": "9"},
  "Skill Check": {"definition": "A Skill Check is an ability check involving a skill. Roll a d20, add the ability modifier, and add Proficiency Bonus if you are proficient in the relevant skill. The GM decides the relevant check.", "examples": ["The GM might ask for Strength (Athletics) when you try to climb a cliff.", "The GM might ask for Intelligence (Investigation) to deduce how a mechanism works."], "why": "Your ability modifier and relevant training both affect the total. Ask the GM what to roll.", "pages": "7–9"},
  "Tool Proficiency": {"definition": "Tool Proficiency lets you add your Proficiency Bonus to an ability check that uses that tool. If you also have proficiency in a skill used for that check, you gain Advantage; do not add the bonus twice.", "examples": ["With Thieves’ Tools proficiency, add your Proficiency Bonus to a check using those tools to pick a lock.", "If a check uses both your proficient skill and your proficient tool, roll with Advantage and add your Proficiency Bonus once."], "why": "Training applies when you actually use the appropriate tool, not to every task involving the same ability.", "pages": "10, 98–99"},
  "Origin Feat": {"definition": "An Origin Feat is a category of feat available through character origins. Your Background grants a specific Origin Feat; some other features can grant one too.", "examples": ["The Criminal Background grants Alert, which adds your Proficiency Bonus to Initiative rolls.", "Skilled grants proficiency in any combination of three skills or tools you choose."], "why": "Read the feat your Background grants; you do not automatically gain every Origin Feat.", "pages": "83, 87"},
  "Ability Score": {"definition": "The six Ability Scores describe your capabilities. Each score has a modifier used for related rolls; your Background allows specific score increases.", "examples": ["Strength 16 has a +3 modifier, so a Strength check starts with d20 + 3 before other bonuses.", "Dexterity 10 has a +0 modifier, so it adds 0 to your Initiative roll before other bonuses."], "why": "Choose scores that support the abilities your Class uses, then apply only the increases your Background permits.", "pages": "6–7, 21–22"},
  "Saving Throw": {"definition": "A Saving Throw is a roll to resist a threat. Roll a d20 and add the relevant ability modifier; add Proficiency Bonus only if you have proficiency in that saving throw.", "examples": ["A Wizard adds Proficiency Bonus to a Wisdom saving throw because the Class grants that proficiency.", "After taking damage while concentrating, you make a Constitution saving throw to try to maintain Concentration."], "why": "Skill proficiency is separate from saving throw proficiency; Perception proficiency does not grant Wisdom save proficiency.", "pages": "7, 9, 179"},
  "Advantage": {"definition": "For a D20 Test with Advantage, roll two d20s and use the higher result. Multiple sources do not add extra dice. Advantage and Disadvantage cancel each other.", "examples": ["If you roll 4 and 17 with Advantage, use 17 before adding your modifiers.", "If a check has both Advantage and Disadvantage, roll one d20 normally."], "why": "Advantage improves the roll; it does not guarantee success or add a flat bonus.", "pages": "8"},
  "Feat":{definition:"A Feat gives your character a specific game benefit. A Background grants one named Origin Feat, not a free pick from every Feat.",examples:["Alert helps you act earlier by adding your Proficiency Bonus to Initiative.","Savage Attacker lets you reroll weapon damage dice under its listed conditions."],why:"Read the granted Feat before deciding. Some benefits need a choice or a manual reminder during play.",pages:"83, 87"},
  "Skill Proficiency":{definition:"Skill Proficiency means adding your Proficiency Bonus to a relevant ability check. Your Background names two trained skills.",examples:["A Sage trained in History adds their bonus when the GM calls for a History check.","A Criminal trained in Stealth adds their bonus when the GM calls for a Stealth check."],why:"Skill training helps a roll but never guarantees that an action succeeds.",pages:"9, 83"},
  "Gaming Set":{definition:"A Gaming Set is a type of tool used for games. A Soldier selects one kind of set to be proficient with.",examples:["A Soldier could choose a Chess Set and use it in a suitable game-related check.","Another Soldier could choose a Dice Set for a game played with dice."],why:"Choosing equipment option A gives your Soldier a Gaming Set of the same kind, not a second different set.",pages:"83, 98–99"},
  "Ability Score Improvement":{definition:"Your Background lets you increase the three listed Ability Scores by a legal pattern. This is different from the level 4 Ability Score Improvement Feat.",examples:["An Acolyte could increase Wisdom by 2 and Intelligence by 1.","A Soldier could increase Strength, Dexterity, and Constitution by 1 each."],why:"Use either +2/+1 on different listed scores or +1 on all three. These increases cannot raise a score above 20.",pages:"20, 83, 87"},
  "Starting Equipment":{definition:"Starting Equipment is the initial gear or money supplied by a game source. Background and Class offer separate choices.",examples:["An Acolyte can choose their listed gear package including 8 GP.","A Criminal can choose 50 GP instead of the listed package."],why:"For each Background select A or B, never both. Review Class equipment independently in Equipment.",pages:"20, 83"},
  "GP":{definition:"GP means Gold Pieces, the standard coin used to buy equipment. It is money, not an extra skill or feat.",examples:["A Background equipment option B supplies 50 GP to spend on gear.","A Soldier taking equipment option A also receives 14 GP with that package."],why:"An option giving 50 GP replaces that Background equipment package; it does not add to it.",pages:"83, 89"},
  "Magic Initiate":{definition:"Magic Initiate is an Origin Feat that grants two cantrips and one level 1 spell from one chosen spell list.",examples:["An Acolyte uses the Cleric spell list for their Magic Initiate choices.","A Sage uses the Wizard spell list for their Magic Initiate choices."],why:"Choose Intelligence, Wisdom, or Charisma as the spellcasting ability. The level 1 spell is always prepared; cast it once without a slot per Long Rest or with a suitable slot. Review these selections in Spells.",pages:"83, 87"}
};

export function beginnerHelp(term) {
  const entry=beginnerTerms[term];
  if(!entry) return '';
  const {definition,examples,pages,why}=entry;
  return `<details class="beginner-help" data-feature-section="help-${term}"><summary>${icon('help')} ${htmlCopy('What is {term}?',{term})}</summary>
    <p>${htmlCopy(definition)}</p><ul>${examples.map(example=>'<li>'+htmlCopy(example)+'</li>').join('')}</ul>
    ${why?'<p>'+htmlCopy(why)+'</p>':''}
    <small>SRD 5.2.1 · ${htmlCopy('Pages {pages}',{pages})}</small></details>`;
}
